#!/usr/bin/env python3
"""Bundle benchmark JSON for previews opened directly with file://."""

import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
SOURCES = ("assets/tasks.json", "assets/results.json")


def javascript_assignment(data):
    """Return JSON-safe JavaScript, including when embedded in an HTML script."""
    payload = json.dumps(data, ensure_ascii=False, allow_nan=False, indent=2)
    payload = payload.replace("</", "<\\/")
    payload = payload.replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    return (
        "// Generated by tools/sync-data.py; edit the source JSON files instead.\n"
        f"window.UNITYBENCH_OFFLINE = {payload};\n"
    )


def main():
    data = {
        name: json.loads((ROOT / name).read_text(encoding="utf-8"))
        for name in SOURCES
    }
    target = ROOT / "assets/benchmark-data.js"
    target.write_text(javascript_assignment(data), encoding="utf-8")
    print(f"Updated {target.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
